import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';

function Button() {
  const [loggedIn, setLoggedIn] = createSignal(false);
  return (
    <button
      class="login-button"
      style={{ '--button-color': loggedIn() ? '#335d92' : 'green' }}
      onClick={() => setLoggedIn((value) => !value)}
    >
      {loggedIn() ? 'Log Out' : 'Log In'}
    </button>
  );
}
function App() {
  return (
    <>
      <Button />
      <Button />
      <style>{`.login-button { background: var(--button-color); color: white; padding: 20px; margin: 10px; }`}</style>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
